/* Reset for consistency */
* { margin: 0; padding: 0; box-sizing: border-box; }
body { 
    font-family: 'Arial', sans-serif; 
    font-size: 16px; 
    line-height: 1.5;
    padding: 20px;
    max-width: 700px;
}

/* Blockquote styles */
blockquote {
    margin: 16px 0;
    padding: 16px 20px;
    border-left: 4px solid #ddd;
    background-color: #f9f9f9;
    font-style: italic;
    color: #666;
}

blockquote p {
    margin: 0;
}

blockquote p:not(:last-child) {
    margin-bottom: 8px;
}

h3 {
    font-size: 20px;
    margin-bottom: 12px;
    font-weight: bold;
}

p {
    margin-bottom: 16px;
}
